        if 0 <= r < len(grid) and 0 <= c < len(grid[0]):
            if grid[r][c] != "X":
                neighbors.append((r, c))

    return neighbors

def get_state_groupings(grid):
    groupings = []

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 0:
                state = [(i, j)]
                stack = [(i, j)]

                while stack:
                    r, c = stack.pop()

                    # Get adjacent states
                    neighbors = get_valid_neighbors(r, c)

                    for nr, nc in neighbors:
                        if (nr, nc) not in state and grid[nr][nc] != "X":
                            state.append((nr, nc))
                            stack.append((nr, nc))

                groupings.append(state)

    return groupings

